#include "flash_page.h"
#include <stdio.h>
#include <string.h>
static tf_model memory;static fp_model page;static fp_backend backend;static uint8_t data[256],known[256];
static unsigned groups,checks,failures,stores,csr_clear,csr_set,keys;
static uint32_t ctrl,ctrl_known,stop_va,first_value,first_known,last_address;static int status_mode,mutate_source,transfer_store,partial_ctrl;
#define A(x) (TF_RAM_BASE+UINT32_C(x))
#define CHECK(x) do{checks++;if(!(x)){failures++;printf("FAIL line=%d %s\n",__LINE__,#x);}}while(0)
static void put(uint32_t off,uint32_t v,uint32_t k){unsigned i;for(i=0;i<4;i++){memory.ram[off+i]=(uint8_t)(v>>(8*i));memory.known[off+i]=(uint8_t)(k>>(8*i));}}
static uint32_t word(uint32_t off){unsigned i;uint32_t v=0;for(i=0;i<4;i++)v|=(uint32_t)memory.ram[off+i]<<(8*i);return v;}
static fp_flow io(void *p,fp_model *m,const fp_request *r,fp_scalar *out){(void)p;CHECK(m==&page&&m->memory==&memory);CHECK(r->width==32);out->value=out->known=0;
 if(r->va==stop_va)return FP_HALT;
 if(r->kind==FP_CSR_CLEAR){CHECK(r->address==0x800&&r->value==136);csr_clear++;return FP_RETURNED;}
 if(r->kind==FP_CSR_SET){CHECK(r->address==0x800&&r->value==136);CHECK(r->va==(m->image==FP_RUNTIME?0x9b9eu:0x2118u));csr_set++;return FP_RETURNED;}
 if(r->kind==FP_READ_REGISTER){if(r->address==0x40022010){out->value=ctrl;out->known=ctrl_known;}else{CHECK(r->address==0x4002200c);out->value=status_mode==1?1u:status_mode==2?2u:0u;out->known=status_mode==3?0u:status_mode==4?3u:UINT32_MAX;}return FP_RETURNED;}
 if(r->kind==FP_WRITE_REGISTER){if(r->address==0x40022004||r->address==0x40022024){CHECK(r->known==UINT32_MAX);CHECK(r->value==0x45670123||r->value==0xcdef89ab);keys++;}else if(r->address==0x40022010){ctrl=r->value;ctrl_known=r->known;if(partial_ctrl)CHECK((r->known&0x10000)!=0||(r->known&0x20000)!=0||(r->known&0x8000)!=0);}else if(r->address==0x40022014){CHECK(r->value==0x08008100||r->value==A(0x100));CHECK(r->known==UINT32_MAX);}else CHECK(r->address==0x4002200c&&r->value==49);return FP_RETURNED;}
 if(r->kind==FP_WORD_STORE){CHECK(r->address==0x08008100+4*stores);if(stores==0){first_value=r->value;first_known=r->known;if(mutate_source){data[4]=0xa5;known[4]=0x0f;}}if(stores==1&&mutate_source){CHECK((r->value&255)==0xa5&&(r->known&255)==15);}last_address=r->address;stores++;return transfer_store?FP_TRANSFER:FP_RETURNED;}
 if(r->kind==FP_SOURCE_READ){if(r->address>=TF_RAM_BASE){CHECK(r->address&3);return FP_HALT;}CHECK(r->address>=0x100&&r->address<0x200);out->value=r->offset;out->known=UINT32_MAX;return FP_RETURNED;}
 return FP_HALT;
}
static void fresh(fp_image image){unsigned i;memset(&memory,0,sizeof(memory));memset(memory.known,255,sizeof(memory.known));memset(&backend,0,sizeof(backend));backend.invoke=io;fp_init(&page,&memory,image,&backend);for(i=0;i<256;i++){data[i]=(uint8_t)i;known[i]=255;}ctrl=0x12345678;ctrl_known=UINT32_MAX;stores=csr_clear=csr_set=keys=0;stop_va=0;first_value=first_known=last_address=0;status_mode=mutate_source=transfer_store=partial_ctrl=0;}
static fp_source view(void){fp_source s;memset(&s,0,sizeof(s));s.kind=FP_VALUE_VIEW;s.data=data;s.known=known;s.available=256;return s;}
static void complete_both(void){unsigned i;fp_source s;groups++;for(i=0;i<2;i++){fresh(i?FP_RUNTIME:FP_BOOT);s=view();CHECK(fp_program_page(&page,0x080081a5,&s)==FP_RETURNED);CHECK(page.words_written==64&&stores==64&&keys==4&&csr_clear==1&&csr_set==1);CHECK(page.destination==0x08008100&&page.raw_destination==0x080081a5);CHECK(first_value==0x03020100&&first_known==UINT32_MAX&&last_address==0x080081fc);CHECK((ctrl&0x30000)==0&&(ctrl&0x208000)==0x208000);}}
static void busy_and_masks(void){fp_source s;groups++;fresh(FP_BOOT);s=view();status_mode=1;page.spin_budget=3;CHECK(fp_program_page(&page,0x08008100,&s)==FP_HALT);CHECK(page.boundary_va==0x3032&&page.needed_mask==1&&stores==0&&csr_set==0);fresh(FP_BOOT);s=view();status_mode=3;CHECK(fp_program_page(&page,0x08008100,&s)==FP_HALT);CHECK(page.boundary_va==0x3032&&page.needed_mask==1&&keys==4);fresh(FP_BOOT);s=view();status_mode=4;partial_ctrl=1;ctrl_known=0;CHECK(fp_program_page(&page,0x08008100,&s)==FP_RETURNED);CHECK(stores==64&&ctrl_known==0x238040);}
static void live_and_unknown_words(void){fp_source s;groups++;fresh(FP_RUNTIME);s=view();mutate_source=1;known[0]=0;CHECK(fp_program_page(&page,0x08008100,&s)==FP_RETURNED);CHECK((first_known&255)==0&&stores==64&&csr_set==1);}
static void missing_view_prefix(void){fp_source s;groups++;fresh(FP_BOOT);s=view();s.available=3;CHECK(fp_program_page(&page,0x08008100,&s)==FP_HALT);CHECK(page.boundary_va==0x3070&&page.source_offset==0&&keys==4&&stores==0&&csr_set==0);CHECK(ctrl&0x10000);}
static void callback_transfer(void){fp_source s;groups++;fresh(FP_RUNTIME);s=view();transfer_store=1;CHECK(fp_program_page(&page,0x08008100,&s)==FP_TRANSFER);CHECK(stores==1&&page.words_written==0&&csr_set==0);fresh(FP_BOOT);s=view();stop_va=0x3000;CHECK(fp_program_page(&page,0x08008100,&s)==FP_HALT);CHECK(keys==1&&csr_clear==1&&csr_set==0);}
static void shared_alias_words(void){fp_source s;unsigned i;groups++;fresh(FP_BOOT);memset(&s,0,sizeof(s));s.kind=FP_ADDRESS;s.address=A(0xfc);for(i=0;i<65;i++)put(0xfc+4*i,i+1,UINT32_MAX);CHECK(fp_program_page(&page,A(0x101),&s)==FP_RETURNED);CHECK(page.words_written==64&&stores==0);for(i=0;i<64;i++)CHECK(word(0x100+4*i)==1);}
static void external_source(void){fp_source s;groups++;fresh(FP_BOOT);memset(&s,0,sizeof(s));s.kind=FP_ADDRESS;s.address=0x100;CHECK(fp_program_page(&page,0x08008100,&s)==FP_RETURNED);CHECK(stores==64&&first_value==0&&first_known==UINT32_MAX);fresh(FP_BOOT);fp_init(&page,&memory,FP_BOOT,NULL);CHECK(fp_program_page(&page,0x08008100,&s)==FP_HALT);CHECK(page.boundary_va==0x20f6&&page.boundary_address==0x800&&stores==0);}
static void helpers(void){fp_source s;unsigned image;uint32_t delta;groups++;for(image=0;image<2;image++){fresh(image?FP_RUNTIME:FP_BOOT);delta=image?0x15c02u:0;s=view();CHECK(fp_dispatch_helper(&page,0x2fea+delta,0,NULL)==FP_RETURNED);CHECK(keys==4&&csr_clear==0&&csr_set==0);CHECK(fp_dispatch_helper(&page,0x2fe2+delta,49,NULL)==FP_RETURNED);CHECK(fp_dispatch_helper(&page,0x3016+delta,0x080081a5,NULL)==FP_RETURNED);CHECK(fp_dispatch_helper(&page,0x3044+delta,0x080081a5,&s)==FP_RETURNED);CHECK(stores==64&&page.words_written==64&&csr_clear==0&&csr_set==0);CHECK(fp_dispatch_helper(&page,0x3008+delta,0,NULL)==FP_RETURNED);CHECK(ctrl&0x8000);}}
static void unaligned_source(void){fp_source s;groups++;fresh(FP_BOOT);memset(&s,0,sizeof(s));s.kind=FP_ADDRESS;s.address=A(0x101);CHECK(fp_program_page(&page,0x08008100,&s)==FP_HALT);CHECK(page.boundary_kind==FP_PRIMITIVE_UNRESOLVED&&page.boundary_va==0x3070&&page.boundary_address==A(0x101));CHECK(stores==0&&csr_clear==1&&csr_set==0&&keys==4);}
int main(void){complete_both();busy_and_masks();live_and_unknown_words();missing_view_prefix();callback_transfer();shared_alias_words();external_source();helpers();unaligned_source();printf("FLASH_PAGE_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no\n",groups,checks,failures);return failures?1:0;}
